function stripUnknownKeys(raw, errors) {
  const keysByParentPath = new Map();
  for (const issue of errors) {
    if (issue.code !== 'unrecognized_keys') continue;
    const parentPath = issue.path.slice(0, issue.path.length - 1);
    const parentKey = parentPath.join('.');
    console.log('Error path:', issue.path, 'parentKey:', parentKey, 'keys:', issue.keys);
    let keys = keysByParentPath.get(parentKey);
    if (!keys) { keys = new Set(); keysByParentPath.set(parentKey, keys); }
    for (const k of issue.keys) { keys.add(k); }
  }
  console.log('keysByParentPath:', [...keysByParentPath.entries()]);

  const strip = (obj, path) => {
    if (obj === null || typeof obj !== 'object') { return obj; }

    const childrenByKey = new Map();
    if (Array.isArray(obj)) {
      for (let i = 0; i < obj.length; i++) { childrenByKey.set(String(i), obj[i]); }
    } else {
      for (const [k, v] of Object.entries(obj)) { childrenByKey.set(k, v); }
    }

    const pathKey = path.join('.');
    console.log('strip called with path:', path, 'pathKey:', pathKey, 'isArray:', Array.isArray(obj));

    const result = Array.isArray(obj) ? [] : {};
    const resultObj = result;

    for (const [key, value] of childrenByKey) {
      const childPath = [...path, key];
      const childKey = childPath.join('.');
      console.log('  processing key:', key, 'childKey:', childKey, 'keysToStrip:', keysByParentPath.get(childKey));
      const keysToStrip = keysByParentPath.get(childKey);

      if (keysToStrip) {
        if (!Array.isArray(obj)) {
          for (const k of Object.keys(obj)) {
            if (keysToStrip.has(k)) continue;
            resultObj[k] = strip(obj[k], childPath);
          }
          return result;
        } else {
          if (!keysToStrip.has(key)) {
            resultObj[key] = strip(value, childPath);
          }
        }
      } else {
        resultObj[key] = strip(value, childPath);
      }
    }
    return result;
  };
  return strip(raw, []);
}

const raw = { agents: { list: [{ id: 'main', thinking: 'adaptive' }] } };
const errors = [{ code: 'unrecognized_keys', path: ['agents', 'list', 0], keys: ['thinking'] }];
console.log('Result:', JSON.stringify(stripUnknownKeys(raw, errors), null, 2));
